import java.io.*;
import java.util.*;

/**
 * Boss of league LEVEL. Each live champion: shoots an enemy in line within RANGE cells when it can;
 * from league 2, guards against a shot that will reach it; otherwise walks to the nearest free crystal
 * (or towards the nearest enemy when no crystal is left). From league 2, it names a race at the start of each round,
 * and as a MAGE it also shoots through walls. In league 3, it only walks to the crystals it can take: those of the opponent's half.
 */
class Player {
    static final int LEVEL = 1, RANGE = 2, W = 15, H = 9;
    static final boolean SOLO = false, TIMING = false;      // test variants only: SOLO plays the first champion of the round alone, TIMING prints the time of each turn
    static final int WANDER = 70;      // % of the turns a champion takes a random step instead of walking to its goal
    static final String[] RACES = {"SKELETON"};      // the race of the boss: one for the match in league 1, then one per round
    static final int[] DX = {0, 0, -1, 1}, DY = {-1, 1, 0, 0};
    static final String[] DIR = {"UP", "DOWN", "LEFT", "RIGHT"};
    static boolean[][] wall = new boolean[H][W];

    static boolean free(int x, int y) { return x >= 0 && y >= 0 && x < W && y < H && !wall[y][x]; }

    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tok;
    static String next() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) tok = new StringTokenizer(in.readLine());
        return tok.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    public static void main(String[] args) throws IOException {
        long worst = 0;
        nextInt(); nextInt();                            // width, height
        for (int y = 0; y < H; y++) {
            String row = next();
            for (int x = 0; x < W; x++) wall[y][x] = row.charAt(x) == '#';
        }
        next();                                          // starts
        int perRound = nextInt();
        Random rnd = new Random(7);
        while (true) {
            int round = nextInt(), turn = nextInt();
            long t0 = System.nanoTime();
            for (int k = 0; k < 4; k++) nextInt();       // scores and crystals
            int n = nextInt();
            List<int[]> champions = new ArrayList<>(), shots = new ArrayList<>(), crystals = new ArrayList<>();
            List<String> cmds = new ArrayList<>();
            List<int[]> coming = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int id = nextInt(); String type = next(); int mine = nextInt(), x = nextInt(), y = nextInt(), shootCooldown = nextInt(), guardCooldown = nextInt();
                nextInt();                               // armour
                int dx = nextInt(), dy = nextInt();
                next();                                  // race
                String c = next();
                if (type.equals("SHOT")) shots.add(new int[] {x, y, dx, dy, mine});
                else if (type.equals("CRYSTAL")) { if (LEVEL < 3 || x > W / 2) crystals.add(new int[] {x, y}); }
                else { champions.add(new int[] {id, x, y, shootCooldown, guardCooldown, mine, type.equals("CHAMPION") ? 1 : 0}); cmds.add(c); }
            }
            // the shots the enemy echoes fire this turn (their commands are in the input): {x, y, dx, dy, 0}
            for (int i = 0; i < champions.size(); i++) {
                int[] r = champions.get(i); String c = cmds.get(i);
                if (r[5] == 1 || r[6] == 1 || c.length() < 2 * turn + 2 || c.charAt(2 * turn) != 'S' || r[3] != 0) continue;
                int d = "UDLR".indexOf(c.charAt(2 * turn + 1));
                coming.add(new int[] {r[1], r[2], DX[d], DY[d], 0, 1});
            }
            StringBuilder out = new StringBuilder();
            Set<Integer> aimed = new HashSet<>();
            for (int s = 0; s < perRound; s++) {
                int myId = round * perRound + s;
                int[] me = null;
                for (int[] r : champions) if (r[0] == myId && r[5] == 1 && r[6] == 1) me = r;
                boolean mage = LEVEL >= 2 && RACES[Math.min(round, RACES.length - 1)].equals("MAGE");
                out.append(s > 0 ? ";" : "").append(me == null || (SOLO && s > 0) ? "WAIT" : act(me, champions, shots, coming, crystals, aimed, rnd, mage));
            }
            if (TIMING) {
                if (round > 0 || turn > 0) worst = Math.max(worst, System.nanoTime() - t0);
                System.err.println("worst turn: " + worst / 1000 + " us");
            }
            boolean named = turn == 0 && (round == 0 || LEVEL >= 2);      // the race of the boss starts its first line of the match, or of each round
            System.out.println(named ? RACES[Math.min(round, RACES.length - 1)] + " " + out : out.toString());
        }
    }

    static String act(int[] me, List<int[]> champions, List<int[]> shots, List<int[]> coming, List<int[]> crystals, Set<Integer> aimed, Random rnd, boolean mage) {
        int x = me[1], y = me[2];
        // 1. shoot an enemy in line
        if (me[3] == 0) for (int d = 0; d < 4; d++) {
            int cx = x, cy = y;
            for (int k = 1; k <= RANGE; k++) {
                cx += DX[d]; cy += DY[d];
                if (cx < 0 || cy < 0 || cx >= W || cy >= H || (wall[cy][cx] && !mage)) break;      // the shots of a MAGE fly through walls
                int[] hit = null;
                for (int[] r : champions) if (r[1] == cx && r[2] == cy) hit = r;
                if (hit != null) { if (hit[5] == 0) return "SHOOT " + DIR[d]; break; }
            }
        }
        // 2. from league 2: guard against an enemy shot that reaches this cell this turn (a shot in flight, or one an echo fires now)
        if (LEVEL >= 2 && me[4] == 0) {
            List<int[]> all = new ArrayList<>(shots);
            all.addAll(coming);
            for (int[] sh : all) {
                if (sh[4] == 1) continue;
                int d = sh[2] == 0 ? (sh[3] < 0 ? 0 : 1) : (sh[2] < 0 ? 2 : 3);
                int cx = sh[0], cy = sh[1];
                for (int k = 1; k <= 2; k++) {
                    cx += DX[d]; cy += DY[d];
                    if (!free(cx, cy)) break;
                    if (cx == x && cy == y) return "GUARD " + DIR[d ^ 1];
                }
            }
        }
        // 3. sometimes a random step
        if (rnd.nextInt(100) < WANDER) {
            int d = rnd.nextInt(4);
            if (free(x + DX[d], y + DY[d])) return "MOVE " + DIR[d];
        }
        // 4. walk to the nearest free crystal nobody else aims at, else towards the nearest enemy
        int[][] dist = bfs(x, y, champions);
        int best = -1, bd = 1 << 20, gx = -1, gy = -1;
        for (int i = 0; i < crystals.size(); i++) {
            int[] c = crystals.get(i);
            if (aimed.contains(i) || dist[c[1]][c[0]] >= 1 << 20) continue;
            if (dist[c[1]][c[0]] < bd) { bd = dist[c[1]][c[0]]; best = i; gx = c[0]; gy = c[1]; }
        }
        if (best >= 0) aimed.add(best);
        else for (int[] r : champions) if (r[5] == 0 && dist[r[2]][r[1]] < bd) { bd = dist[r[2]][r[1]]; gx = r[1]; gy = r[2]; }
        if (gx < 0) return "WAIT";
        // step back from the goal along the distances
        int[][] back = bfs(gx, gy, champions);
        int bestD = -1, bv = back[y][x];
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d], ny = y + DY[d];
            if (free(nx, ny) && back[ny][nx] < bv) { bv = back[ny][nx]; bestD = d; }
        }
        return bestD < 0 ? "WAIT" : "MOVE " + DIR[bestD];
    }

    /** Distances from a cell, around walls (champions are not obstacles: they move). */
    static int[][] bfs(int sx, int sy, List<int[]> champions) {
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, 1 << 20);
        ArrayDeque<int[]> q = new ArrayDeque<>();
        dist[sy][sx] = 0;
        q.add(new int[] {sx, sy});
        while (!q.isEmpty()) {
            int[] c = q.poll();
            for (int d = 0; d < 4; d++) {
                int nx = c[0] + DX[d], ny = c[1] + DY[d];
                if (free(nx, ny) && dist[ny][nx] > dist[c[1]][c[0]] + 1) { dist[ny][nx] = dist[c[1]][c[0]] + 1; q.add(new int[] {nx, ny}); }
            }
        }
        return dist;
    }
}

