            if (free(nx, ny) && back[ny][nx] < bv) { bv = back[ny][nx]; bestD = d; }
        }
        return bestD < 0 ? "WAIT" : "MOVE " + DIR[bestD];
    }

    /** Distances from a cell, around walls (champions are not obstacles: they move). */
    static int[][] bfs(int sx, int sy, List<int[]> champions) {
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, 1 << 20);
        ArrayDeque<int[]> q = new ArrayDeque<>();
        dist[sy][sx] = 0;
        q.add(new int[] {sx, sy});
        while (!q.isEmpty()) {
            int[] c = q.poll();
            for (int d = 0; d < 4; d++) {
                int nx = c[0] + DX[d], ny = c[1] + DY[d];
                if (free(nx, ny) && dist[ny][nx] > dist[c[1]][c[0]] + 1) { dist[ny][nx] = dist[c[1]][c[0]] + 1; q.add(new int[] {nx, ny}); }
            }
        }
        return dist;
    }
}
